 "content": "def transform(grid):
    out = [row[:] for row in grid]
    active = [r for r, row in enumerate(grid) if any(v != 0 for v in row)]
    blocks = []
    for r in active:
        if not blocks or r > blocks[-1][-1] + 1:
            blocks.append([r])
        else:
            blocks[-1].append(r)
    if len(blocks) < 2:
        return out
    first, second = blocks[0][0], blocks[1][0]
    end_first = max(c for c, v in enumerate(grid[first]) if v != 0)
    end_second = max(c for c, v in enumerate(grid[second]) if v != 0)
    if end_first < end_second:
        short_row, other_row = first, second
    else:
        short_row, other_row = second, first
    end = max(c for c, v in enumerate(grid[short_row]) if v != 0)
    for c in range(end + 1, len(grid[0])):
        if grid[other_row][c] != 0:
            out[short_row][c] = 1
    return out
