 "content": "from collections import Counter


def transform(grid):
    """Balance substantial row-population differences between the two bands.

    For each vertically corresponding pair of rows in the two non-background
    bands, add 1s to the right-hand blank suffix of the sparser row until the
    row populations match (when the difference is at least 3).
    """
    out = [row[:] for row in grid]
    if not grid:
        return out

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active_rows:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) != 2 or len(bands[0]) != len(bands[1]):
        return out

    for ra, rb in zip(bands[0], bands[1]):
        ca = sum(v != bg for v in grid[ra])
        cb = sum(v != bg for v in grid[rb])
        delta = abs(ca - cb)
        if delta < 3:
            continue
        target = ra if ca < cb else rb
        last = max((c for c, v in enumerate(grid[target]) if v != bg), default=-1)
        end = min(len(out[target]), last + 1 + delta)
        for c in range(last + 1, end):
            if out[target][c] == bg:
                out[target][c] = 1
    return out


if __name__ == "__main__":
    pass
