 "content": "from collections import Counter


def transform(grid):
    """Copy the longer aligned row's trailing mask into the shorter row as 1s.

    The two separated bands contain aligned strings of small motifs.  Their
    common/encoded body is left untouched; when one aligned row has a longer
    right-hand continuation, copy only its non-background suffix mask into the
    other row, using color 1.
    """
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    if len(bands) != 2 or len(bands[0]) != len(bands[1]):
        return out

    for upper_r, lower_r in zip(*bands):
        upper_last = max((c for c, v in enumerate(grid[upper_r]) if v != bg), default=-1)
        lower_last = max((c for c, v in enumerate(grid[lower_r]) if v != bg), default=-1)
        if upper_last == lower_last:
            continue

        source_r, target_r, target_last = (
            (upper_r, lower_r, lower_last) if upper_last > lower_last
            else (lower_r, upper_r, upper_last)
        )
        for c in range(target_last + 1, len(grid[target_r])):
            if grid[source_r][c] != bg and grid[target_r][c] == bg:
                out[target_r][c] = 1
    return out


if __name__ == "__main__":
    pass
