def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) != 2 or len(bands[0]) != len(bands[1]):
        return out
    upper, lower = bands
    # Mark with 1 the foreground overhang in the band extending farther right.
    upper_end = max(c for r in upper for c, v in enumerate(grid[r]) if v != bg)
    lower_end = max(c for r in lower for c, v in enumerate(grid[r]) if v != bg)
    if upper_end == lower_end:
        return out
    if upper_end > lower_end:
        long_band, short_band, start = upper, lower, lower_end + 1
    else:
        long_band, short_band, start = lower, upper, upper_end + 1
    for long_r, short_r in zip(long_band, short_band):
        for c in range(start, len(grid[0])):
            if grid[long_r][c] != bg and grid[short_r][c] == bg:
                out[long_r][c] = 1
    return out
