 "new_string": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) != 2 or len(bands[0]) != len(bands[1]):
        return out

    ends = [max(c for r in band for c, v in enumerate(grid[r]) if v != bg)
            for band in bands]
    if ends[0] == ends[1]:
        return out
    source_i = 0 if ends[0] > ends[1] else 1
    target_i = 1 - source_i
